def runs(grid):
    R=[]
    h,w=grid.shape
    for r in range(h):
        c=0
        while c<w:
            v=grid[r,c]
            if v!=6:
                c0=c
                while c<w and grid[r,c]==v: c+=1
                if c-c0>=3: R.append(('H',r,c0,c-1,v))
