import numpy as np
from collections import defaultdict

def get_objs(I):
    bg=int(np.bincount(I.flatten()).argmax())
    CC=comps_c(I,bg)
    return bg,[(col,c) for col,cl in CC.items() for c in cl]

def find_L(objs):
    cands=[]
    for col,c in objs:
        rows=set(r for r,_ in c); cols=set(x for _,x in c); s=set(c)
        for r0 in rows:
            for c0 in cols:
                vert={p for p in s if p[1]==c0}; horz={p for p in s if p[0]==r0}
                if s<=vert|horz and len(vert)>=3 and len(horz)>=3:
                    cands.append(c); break
            else: continue
            break
    return max(cands,key=len) if cands else None

